import{_ as r,C as a,o as n,c as i,a2 as t,E as o}from"./chunks/framework.TaNiW7i8.js";const f=JSON.parse('{"title":"Premier lancement","description":"","frontmatter":{"title":"Premier lancement"},"headers":[],"relativePath":"guide/first-run.md","filePath":"guide/first-run.md"}'),l={name:"guide/first-run.md"};function u(c,e,d,p,m,h){const s=a("Capture");return n(),i("div",null,[e[0]||(e[0]=t('<h1 id="premier-lancement" tabindex="-1">Premier lancement <a class="header-anchor" href="#premier-lancement" aria-label="Permalink to &quot;Premier lancement&quot;">​</a></h1><p>Au premier lancement, Kessho ne connaît encore ni vous ni votre mémoire. Au lieu de l&#39;accueil, il ouvre un assistant en cinq étapes : qui vous êtes, où vit la mémoire, ce qu&#39;elle contient, quels assistants IA la connaissent, puis un récapitulatif.</p><p>À gauche, un panneau sombre garde la marque et la liste des étapes : <strong>Identité</strong>, <strong>Emplacement</strong>, <strong>Reconnaissance</strong>, <strong>Connecteurs</strong>, <strong>Récapitulatif</strong>. À droite, l&#39;étape en cours, annoncée en haut (« Étape 2 sur 5 »).</p><h2 id="les-etapes" tabindex="-1">Les étapes <a class="header-anchor" href="#les-etapes" aria-label="Permalink to &quot;Les étapes&quot;">​</a></h2><h3 id="_1-votre-profil" tabindex="-1">1. Votre profil <a class="header-anchor" href="#_1-votre-profil" aria-label="Permalink to &quot;1. Votre profil&quot;">​</a></h3><ol><li>Écrivez votre nom dans <strong>Nom ou Pseudo</strong>. C&#39;est la façon dont l&#39;assistant s&#39;adressera à vous.</li><li>Si vous le souhaitez, ajoutez un <strong>Courriel</strong>. Il est facultatif ; s&#39;il est rempli, il doit ressembler à une adresse, sinon l&#39;écran affiche « Cette adresse ne peut pas en être une ».</li><li>Cliquez sur <strong>Continuer vers l&#39;emplacement de la mémoire</strong>. Le bouton reste grisé tant que le nom est vide ou que le courriel saisi n&#39;est pas plausible.</li></ol><h3 id="_2-l-emplacement-de-la-memoire" tabindex="-1">2. L&#39;emplacement de la mémoire <a class="header-anchor" href="#_2-l-emplacement-de-la-memoire" aria-label="Permalink to &quot;2. L&#39;emplacement de la mémoire&quot;">​</a></h3>',7)),o(s,{name:"premier-lancement",alt:"Le premier lancement, étape 2 sur 5 : choisir le dossier qui sera la mémoire (dossier existant, installation précédente ou nouvelle mémoire)."}),e[1]||(e[1]=t('<p>Kessho vous propose des emplacements trouvés sur votre machine, chacun avec son nombre de notes (« n&#39;existe pas encore » à la place pour une nouvelle mémoire) :</p><ul><li><strong>Nouvelle mémoire Kessho</strong> : un dossier à créer, marqué « n&#39;existe pas encore » ;</li><li><strong>Dossier existant</strong> : un dossier de notes déjà là, par exemple un dossier Obsidian ;</li><li><strong>Installation précédente</strong> : le dossier d&#39;une installation précédente, détecté sur votre poste.</li></ul><p>Une proposition marquée « lecture seule » refuse l&#39;écriture sur ce poste : mieux vaut en choisir une autre.</p><ol><li>Cliquez sur la proposition qui vous convient. Le champ <strong>Chemin de la mémoire</strong> se remplit.</li><li>Ou tapez un chemin dans ce champ, ou cliquez sur <strong>Parcourir…</strong> pour choisir un dossier.</li><li>Cliquez sur <strong>Suivant</strong>. Le bouton reste grisé tant que le chemin est vide. <strong>Retour</strong> revient à l&#39;étape précédente.</li></ol><p>Pour comprendre ces choix, voir <a href="/Kessho/guide/vault.html">Choisir sa mémoire</a>. L&#39;écran le rappelle : « Modifiable ensuite dans les réglages. »</p><h3 id="_3-la-reconnaissance" tabindex="-1">3. La reconnaissance <a class="header-anchor" href="#_3-la-reconnaissance" aria-label="Permalink to &quot;3. La reconnaissance&quot;">​</a></h3><p>Kessho parcourt le dossier pour vous montrer ce qu&#39;il contient. Rien n&#39;est enregistré, et rien ne vous empêche de continuer.</p><ol><li>Cliquez sur <strong>Parcourir le dossier</strong>.</li><li>Une barre avance, avec le compte « 12 / 184 fichiers lus » et le temps écoulé. Si certains fichiers posent problème, les premiers avertissements (cinq au plus) s&#39;affichent dessous.</li><li>Cliquez sur <strong>Suivant</strong> quand la lecture est finie. Vous pouvez aussi cliquer sur <strong>Passer cette étape</strong> sans rien parcourir.</li></ol><h3 id="_4-les-connecteurs" tabindex="-1">4. Les connecteurs <a class="header-anchor" href="#_4-les-connecteurs" aria-label="Permalink to &quot;4. Les connecteurs&quot;">​</a></h3><p>Vos assistants peuvent interroger votre mémoire — à condition de la connaître. Rien n&#39;est écrit tant que vous ne le demandez pas.</p><ol><li>Cliquez sur <strong>Déclarer Kessho à mes assistants</strong>.</li><li>Kessho liste les assistants qu&#39;il connaît, chacun suivi de « déclaré » ou de « non détecté » (pas installé sur ce poste : ce n&#39;est pas une panne).</li><li>Cliquez sur <strong>Suivant</strong>, ou sur <strong>Passer cette étape</strong> pour le faire plus tard.</li></ol><p>Cette étape fait la même chose que le bouton <strong>Auto-injecter</strong> des réglages. Le détail est dans <a href="/Kessho/guide/agents.html">Connecter ses agents</a>.</p><h3 id="_5-le-recapitulatif" tabindex="-1">5. Le récapitulatif <a class="header-anchor" href="#_5-le-recapitulatif" aria-label="Permalink to &quot;5. Le récapitulatif&quot;">​</a></h3><p>L&#39;écran « Confirmation &amp; finalisation » reprend vos choix : <strong>Utilisateur</strong> et <strong>Emplacement de la mémoire</strong>.</p><ol><li>Vérifiez les deux valeurs. <strong>Modifier</strong> revient en arrière.</li><li>Cliquez sur <strong>Lancer Kessho</strong>. La configuration est enregistrée (« Enregistrement… ») et l&#39;application s&#39;ouvre.</li></ol><p>Si l&#39;enregistrement échoue, le message « Erreur lors de la sauvegarde de la configuration » s&#39;affiche et vous restez sur l&#39;écran.</p><h2 id="ce-qui-est-obligatoire" tabindex="-1">Ce qui est obligatoire <a class="header-anchor" href="#ce-qui-est-obligatoire" aria-label="Permalink to &quot;Ce qui est obligatoire&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Étape</th><th>Peut-on la passer ?</th></tr></thead><tbody><tr><td>Identité</td><td>Non : il faut un nom.</td></tr><tr><td>Emplacement</td><td>Non : il faut un chemin.</td></tr><tr><td>Reconnaissance</td><td>Oui, avec <strong>Passer cette étape</strong>.</td></tr><tr><td>Connecteurs</td><td>Oui, avec <strong>Passer cette étape</strong>.</td></tr><tr><td>Récapitulatif</td><td>Non : c&#39;est lui qui enregistre.</td></tr></tbody></table><h2 id="relancer-l-assistant" tabindex="-1">Relancer l&#39;assistant <a class="header-anchor" href="#relancer-l-assistant" aria-label="Permalink to &quot;Relancer l&#39;assistant&quot;">​</a></h2><p>Pour le refaire, ouvrez <strong>Réglages</strong>, section <strong>Réinitialisation</strong>, puis <strong>Relancer l&#39;assistant d&#39;Onboarding</strong>. La configuration est remise à zéro ; la mémoire et son contenu ne sont pas touchés. Le bouton agit tout de suite, sans demander de confirmation. Voir <a href="/Kessho/guide/settings.html">Réglages</a>.</p><h2 id="et-ensuite" tabindex="-1">Et ensuite ? <a class="header-anchor" href="#et-ensuite" aria-label="Permalink to &quot;Et ensuite ?&quot;">​</a></h2><p>Une fois l&#39;assistant fermé, l&#39;application s&#39;ouvre. Découvrez l&#39;<a href="/Kessho/guide/home.html">Accueil</a>.</p>',22))])}const v=r(l,[["render",u]]);export{f as __pageData,v as default};
